import React, { useEffect, useState } from "react";

export default function ActivityFilterModal({
  isOpen,
  onClose,
  filters,
  setFilters,
  onReset,
  exportFormat,
  setExportFormat,
}) {

  const [showAdvanced, setShowAdvanced] = useState(false);

  const toggleArrayValue = (key, value) => {
    setFilters((prev) => {
      const current = prev[key];
      const exists = current.includes(value);

      return {
        ...prev,
        [key]: exists
          ? current.filter((v) => v !== value)
          : [...current, value],
      };
    });
  };

  const updateFilterValue = (key, value) => {
    setFilters((prev) => ({
      ...prev,
      [key]: value === "" ? "" : value,
    }));
  };

  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === "Escape") onClose();
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [onClose]);

  
  
  useEffect(() => {
    const hasAdvancedFilters =
      filters.distanceMin ||
      filters.distanceMax ||
      filters.durationMin ||
      filters.durationMax ||
      filters.paceMin ||
      filters.paceMax ||
      filters.feels.length > 0 ||
      filters.dateStart ||
      filters.dateEnd ||
      filters.notesSearch;

    if (hasAdvancedFilters) {
      setShowAdvanced(true);
    }
  }, [filters]);



  if (!isOpen) return null;


  return (
    <div className="modal-overlay" onClick={onClose}>
      <div
        className="activity-filter-modal"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="activity-filter-header">
          <h2>Filter Activities</h2>
          <button className="modal-close-btn" onClick={onClose}>
            ✕
          </button>
        </div>

        <div className="activity-filter-body">


          <div className="row">
            <div className="filter-group">
              <label className="filter-label">Search by name</label>
              <input
                type="text"
                className="filter-input"
                placeholder="Search title..."
                value={filters.searchName}
                onChange={(e) =>
                  setFilters((prev) => ({ ...prev, searchName: e.target.value }))
                }
              />
            </div>

            <div className="filter-group">
              <label className="filter-label">Search by date</label>
              <input
                type="date"
                className="filter-input"
                value={filters.searchDate}
                onChange={(e) =>
                  setFilters((prev) => ({ ...prev, searchDate: e.target.value }))
                }
              />
            </div>
          </div>
          

          <div className="filter-group">
            <label className="filter-label">Activity type</label>

            <div className="filter-chip-row">
              {[
                { label: "Run", value: "run" },
                { label: "Bike", value: "bike" },
                { label: "Swim", value: "swim" },
                { label: "Workout", value: "workout" },
              ].map((item) => (
                <button
                  key={item.value}
                  type="button"
                  className={`filter-chip ${
                    filters.types.includes(item.value) ? "active" : ""
                  }`}
                  onClick={() => toggleArrayValue("types", item.value)}
                >
                  {item.label}
                </button>
              ))}
            </div>
          </div>

          <div className="filter-group">
            <label className="filter-label">Intensity</label>
            <div className="filter-chip-row">
              {[
                { label: "Easy", value: "easy" },
                { label: "Tempo", value: "tempo" },
                { label: "Sprint", value: "intervals" },
                { label: "Long", value: "long" },
              ].map((item) => (
                <button
                  key={item.value}
                  type="button"
                  className={`filter-chip chip-${item.value} ${
                    filters.intensities.includes(item.value) ? "active" : ""
                  }`}
                  onClick={() => toggleArrayValue("intensities", item.value)}
                >
                  {item.label}
                </button>
              ))}
            </div>
          </div>

          <div className="filter-group">
            <label className="filter-checkbox-row">
              <input
                type="checkbox"
                checked={filters.prOnly}
                onChange={(e) =>
                  setFilters((prev) => ({ ...prev, prOnly: e.target.checked }))
                }
              />
              <span>Show PRs only</span>
            </label>
          </div>

          <div className="filter-group">
            <label className="filter-label">Sort by</label>
            <select
              className="filter-select"
              value={filters.sortBy}
              onChange={(e) => updateFilterValue("sortBy", e.target.value)}
            >
              <option value="newest">Newest First</option>
              <option value="fastestPace">Fastest Pace</option>
              <option value="longestDistance">Longest Distance</option>
              <option value="longestTime">Longest Time</option>
            </select>

            <button
              type="button"
              className="advanced-settings-toggle"
              onClick={() => setShowAdvanced((prev) => !prev)}
            >
              {showAdvanced ? "Hide Advanced Settings" : "Advanced Settings"}
            </button>
          </div>

          {showAdvanced && (
            <div className="advanced-settings-section">

              <div className="row">
                <div className="filter-group">
                  <label className="filter-label">Distance range (miles)</label>
                  <div className="range-row">
                    <input
                      type="number"
                      className="filter-input"
                      placeholder="Min"
                      value={filters.distanceMin}
                      onChange={(e) => updateFilterValue("distanceMin", e.target.value)}
                    />
                    <input
                      type="number"
                      className="filter-input"
                      placeholder="Max"
                      value={filters.distanceMax}
                      onChange={(e) => updateFilterValue("distanceMax", e.target.value)}
                    />
                  </div>
                </div>

                <div className="filter-group">
                  <label className="filter-label">Duration range (minutes)</label>
                  <div className="range-row">
                    <input
                      type="number"
                      className="filter-input"
                      placeholder="Min"
                      value={filters.durationMin}
                      onChange={(e) => updateFilterValue("durationMin", e.target.value)}
                    />
                    <input
                      type="number"
                      className="filter-input"
                      placeholder="Max"
                      value={filters.durationMax}
                      onChange={(e) => updateFilterValue("durationMax", e.target.value)}
                    />
                  </div>
                </div>
              </div>

              <div className="row">
                <div className="filter-group">
                  <label className="filter-label">Pace filter (min/mi)</label>
                  <div className="range-row">
                    <input
                      type="number"
                      step="0.01"
                      className="filter-input"
                      placeholder="Min pace"
                      value={filters.paceMin}
                      onChange={(e) => updateFilterValue("paceMin", e.target.value)}
                    />
                    <input
                      type="number"
                      step="0.01"
                      className="filter-input"
                      placeholder="Max pace"
                      value={filters.paceMax}
                      onChange={(e) => updateFilterValue("paceMax", e.target.value)}
                    />
                  </div>
                </div>

                <div className="filter-group">
                  <label className="filter-label">Date range</label>
                  <div className="range-row">
                    <input
                      type="date"
                      className="filter-input"
                      value={filters.dateStart}
                      onChange={(e) => updateFilterValue("dateStart", e.target.value)}
                    />
                    <input
                      type="date"
                      className="filter-input"
                      value={filters.dateEnd}
                      onChange={(e) => updateFilterValue("dateEnd", e.target.value)}
                    />
                  </div>
                </div>
              </div>

              <div className="filter-group">
                <label className="filter-label">Feel</label>
                <div className="filter-chip-row">
                  {[
                    { label: "Easy", value: "easy" },
                    { label: "Medium", value: "medium" },
                    { label: "Hard", value: "hard" },
                  ].map((item) => (
                    <button
                      key={item.value}
                      type="button"
                      className={`filter-chip ${
                        filters.feels.includes(item.value) ? "active" : ""
                      }`}
                      onClick={() => toggleArrayValue("feels", item.value)}
                    >
                      {item.label}
                    </button>
                  ))}
                </div>
              </div>

              <div style={{ height: "14px" }}></div>

              <div className="filter-group">
                <label className="filter-label">Notes search</label>
                <input
                  type="text"
                  className="filter-input"
                  placeholder="Search notes and descriptions..."
                  value={filters.notesSearch}
                  onChange={(e) => updateFilterValue("notesSearch", e.target.value)}
                />
              </div>

              <div style={{ height: "14px" }}></div>

              <div className="filter-group">
                <label className="filter-label">Export format</label>
                <select
                  className="filter-select"
                  value={exportFormat}
                  onChange={(e) => setExportFormat(e.target.value)}
                >
                  <option value="xlsx">Excel (.xlsx)</option>
                  <option value="csv">CSV (.csv)</option>
                </select>
              </div>



            </div>
          )}
          

        </div>

        <div className="activity-filter-footer">
          <button type="button" className="control-btn btn-secondary" onClick={onReset}>
            Reset
          </button>

          <button type="button" className="control-btn" onClick={onClose}>
            Done
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { FiImage, FiUpload } from "react-icons/fi";
import { FaRunning, FaBiking, FaSwimmingPool } from "react-icons/fa";

function getLocalTodayYMD() {
  const now = new Date();
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, "0");
  const d = String(now.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}


// Schema

/*
{
  "id": "string",
  "title": "string",
  "description": "string",
  "type": "run | bike | swim | workout",
  "intensity": "easy | tempo | intervals | long",
  "feel": "easy | medium | hard",
  "limiter": "string",
  "tags": ["string"],
  "date": "YYYY-MM-DD",
  "time": "HH:MM",
  "mode": "timeMiles | splits",
  "miles": "number",
  "duration": "number",
  "splits": [
    {
      "mph": "number",
      "distance": "number"
    }
  ],
  "notes": "string",
  "photo": "base64-string"
}
*/

const TAG_OPTIONS = [
  
  { value: "strides", label: "⚡ Strides" },
  { value: "drills", label: "🎯 Drills" },
  { value: "hills", label: "⛰️ Hills" },
  { value: "recovery", label: "🛟 Recovery" },

  { value: "trail", label: "🌲 Trail" },
  
  { value: "brick", label: "🧱 Brick" },
  { value: "race", label: "🏁 Race" },
  
  
  
];

export default function AddActivityModal({ isOpen, onClose, onSave, initialActivity, onDelete }) {

  const today = getLocalTodayYMD();

  const emptyForm = {
    id: null,
    title: "",
    description: "",
    type: "run",
    intensity: "easy",
    feel: "medium",
    limiter: "",
    tags: [],
    date: today,
    time: "",
    mode: "timeMiles", // or "splits"
    duration: "",
    miles: "",
    splits: [{ mph: "", distance: "" }],
    notes: "",
    photo: null, // will be base64 string
  };

  const [form, setForm] = useState(emptyForm);

  // When the modal opens, if we're editing, preload the form.
  // If we're adding, reset to empty defaults.
  useEffect(() => {
    if (!isOpen) return;

    if (initialActivity) {
      setForm({
        ...initialActivity, // copy activity FIRST

        limiter: initialActivity.limiter ?? "",
        tags: Array.isArray(initialActivity.tags) ? [...initialActivity.tags] : [],
        splits: initialActivity.splits?.length
          ? initialActivity.splits.map((s) => ({
              mph: s.mph ?? "",
              distance: s.distance ?? "",
            }))
          : [{ mph: "", distance: "" }],

        date: initialActivity.date ?? today,
      });
    } else {
      setForm({
        ...emptyForm,
        tags: [],
        splits: [{ mph: "", distance: "" }],
      });
    }

  }, [isOpen, initialActivity]);

  if (!isOpen) return null;

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSplitChange = (index, field, value) => {
    setForm((prev) => ({
      ...prev,
      splits: prev.splits.map((split, i) =>
        i === index ? { ...split, [field]: value } : split
      ),
    }));
  };

  const toggleTag = (tagValue) => {
    setForm((prev) => {
      const hasTag = prev.tags.includes(tagValue);

      return {
        ...prev,
        tags: hasTag
          ? prev.tags.filter((tag) => tag !== tagValue)
          : [...prev.tags, tagValue],
      };
    });
  };

  const addSplit = () => {
    setForm((prev) => ({
      ...prev,
      splits: [...prev.splits, { mph: "", distance: "" }],
    }));
  };

  const handleSubmit = () => {
    const activityToSave = {
      ...form,
      id: initialActivity?.id ?? form.id ?? null,
    };

    onSave(activityToSave);
    onClose();


    console.log("hiiiiiiiiii");

    // trigger jar animation ONLY for easy runs
    if (
      activityToSave.type === "run" &&
      activityToSave.intensity === "easy" &&
      Number(activityToSave.miles) > 0 &&
      Number(activityToSave.duration) > 0
    ) {
      localStorage.setItem("jarDrop", "true");
    }

    // Tell next page load to play sound
    // (You can't refresh and play the sound here at the same time 
    // you need to use activity.jsx to play while this refreshes)

    localStorage.setItem("playActivitySound", "true");

    // 📳 Vibrate (mobile only)
    if (navigator.vibrate) {
      navigator.vibrate(120);
    }

    // Slight delay to have the reload match up with the sound
    setTimeout(() => {
      window.location.reload();
    }, 675);
    
  };

  return (
    <>
      <div className="overlay" onClick={onClose}></div>
        
      <div className="modal slide-in">

        <h2>{initialActivity ? "Edit Activity" : "Manual Activity"}</h2>

        <button className="close-btn" onClick={onClose}>
          ✕
        </button>

        <input
          name="title"
          placeholder="Title your run"
          value={form.title}
          onChange={handleChange}
        />

        <textarea
          name="description"
          placeholder="How'd it go?"
          value={form.description}
          onChange={handleChange}
        />

      <div className="toggle-group">
        <button
          className={form.mode === "timeMiles" ? "active" : ""}
          onClick={() =>
            setForm((prev) => ({
              ...prev,
              mode: "timeMiles",
            }))
          }
        >
          Miles + Time
        </button>

        <button
          className={form.mode === "splits" ? "active" : ""}
          onClick={() =>
            setForm((prev) => ({
              ...prev,
              mode: "splits",
            }))
          }
        >
          MPH + Splits
        </button>
      </div>

      {form.mode === "timeMiles" && (
        <>
          <input
            name="miles"
            placeholder="Miles"
            value={form.miles}
            onChange={handleChange}
          />

          <input
            name="duration"
            placeholder="Duration (minutes)"
            value={form.duration}
            onChange={handleChange}
          />
        </>
      )}

        {form.mode === "splits" && (
          <>
            {form.splits.map((split, i) => (
              <div key={i}>
                <input
                  placeholder="MPH"
                  value={split.mph}
                  onChange={(e) =>
                    handleSplitChange(i, "mph", e.target.value)
                  }
                />
                <input
                  placeholder="Distance"
                  value={split.distance}
                  onChange={(e) =>
                    handleSplitChange(i, "distance", e.target.value)
                  }
                />
              </div>
            ))}
            <button onClick={addSplit}>+ Add Split</button>
          </>
        )}

        {/* Keep these as selects */}
        <div className="row" style={{ marginBottom: "0px" }}>
          <select name="type" value={form.type} onChange={handleChange}>
            <option value="run">🏃‍➡️ Run</option>
            <option value="bike">🚲 Bike</option>
            <option value="swim">🥽 Swim</option>
            <option value="workout">💪 Workout</option>
          </select>

          <select name="limiter" value={form.limiter} onChange={handleChange}>
            <option value="">⚪ No Limiter</option>

            <option value="heavy">🪨 Heavy Legs</option>
            <option value="lungs">🫁 Lungs Stopped Me</option>
            <option value="muscle_burn">🔥 Muscle Burn</option>
            <option value="joint_pain">⚠️ Foot / Knee / Hip Felt Sus</option>
            <option value="energy_low">🔋 Low Energy</option>
            <option value="heat">🥵 Heat</option>
            <option value="sleepy">😴 Poor Sleep</option>
            <option value="stomach">🤢 Stomach Issues</option>
            <option value="bored">😒 Bored</option>
          </select>
        </div>

        <div className="row">
          <select name="intensity" value={form.intensity} onChange={handleChange}>
            <option value="easy">🟢 Easy</option>
            <option value="tempo">🟡 Tempo</option>
            <option value="intervals">🔴 Intervals</option>
            <option value="long">🟣 Long</option>
          </select>

          <select name="feel" value={form.feel} onChange={handleChange}>
            <option value="easy">🍃 Light</option>
            <option value="medium">😎 Steady</option>
            <option value="hard">🔥 Tough</option>
          </select>
        </div>

        

        <div className="tag-section">
          <h3>Tags</h3>

          <div className="tag-group">
            {TAG_OPTIONS.map((tag) => {
              const isActive = form.tags.includes(tag.value);

              return (
                <button
                  key={tag.value}
                  type="button"
                  className={`tag-pill ${isActive ? "active" : ""}`}
                  onClick={() => toggleTag(tag.value)}
                >
                  {tag.label}
                </button>
              );
            })}
          </div>
        </div>

        <div style={{ height: "20px" }}></div>

        {/* Upload image */}
        <label className="upload-box">
          <input
            type="file"
            className="upload-input"
            onChange={(e) => {
              const file = e.target.files?.[0];
              if (!file) return;

              const reader = new FileReader();
              reader.onloadend = () => {
                setForm((prev) => ({
                  ...prev,
                  photo: reader.result,
                }));
              };
              reader.readAsDataURL(file);
            }}
          />

          <div className="upload-content">
            <div className="upload-icon">
              <FiImage />
            </div>
            <div className="upload-text">Add Photos / Videos</div>
          </div>
        </label>

        {form.photo && (
          <div style={{ marginTop: 10 }}>
            <img
              src={form.photo}
              alt="preview"
              style={{ width: "100%", borderRadius: 12 }}
            />
          </div>
        )}

        <h3>Activity Stats</h3>

        <div className="row">
          <input type="date" name="date" value={form.date} onChange={handleChange} />
          <input type="time" name="time" value={form.time} onChange={handleChange} />
        </div>



        <textarea
          name="notes"
          placeholder="Private Notes"
          value={form.notes}
          onChange={handleChange}
        />

        {/* Save button */}
        <button className="primary-btn" onClick={handleSubmit}>
          Save Activity
        </button>

        {/* Delete button */}
        {initialActivity && (
          <button
            type="button"
            className="danger-btn"
            onClick={() => {
              if (!form.id) return;
              onDelete(form.id);
              onClose();
            }}
          >
            Delete Activity
          </button>
        )}


      </div>
    </>
  );
}

import React, { useMemo } from "react";

/*
  GitHub-style activity heatmap
  - 7 rows = days of week
  - columns = weeks
  - each square = one day
  - month labels shown across top
*/

function parseLocalYMD(input) {
  if (!input) return null;
  if (input instanceof Date) return input;

  const clean = String(input).split("T")[0];

  // YYYY-MM-DD
  if (clean.includes("-")) {
    const [y, m, d] = clean.split("-").map(Number);
    if (!y || !m || !d) return null;
    return new Date(y, m - 1, d);
  }

  // M/D/YYYY
  if (clean.includes("/")) {
    const [m, d, y] = clean.split("/").map(Number);
    if (!y || !m || !d) return null;
    return new Date(y, m - 1, d);
  }

  return null;
}

const pad2 = (n) => String(n).padStart(2, "0");
const toYMD = (d) =>
  `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;

function startOfDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function addDays(date, days) {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

function startOfWeekSunday(date) {
  const d = startOfDay(date);
  const day = d.getDay(); // 0 = Sun
  return addDays(d, -day);
}

function sameMonth(a, b) {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth()
  );
}

function getActivityScore(activity) {
  const type = String(
    activity?.type || activity?.sport || activity?.activityType || "run"
  ).toLowerCase();

  const miles = Number(activity?.miles ?? 0);
  const minutes = Number(
    activity?.minutes ??
      activity?.duration ??
      activity?.durationMin ??
      activity?.durationMinutes ??
      0
  );
  const feel = String(activity?.feel || "").toLowerCase();

  // You can tweak these however you want later.
  // For now:
  // - runs/bikes/swims mainly reward distance
  // - workouts reward effort + some time

  if (type === "run") {
    if (Number.isFinite(miles) && miles > 0) return miles;
    if (Number.isFinite(minutes) && minutes > 0) return minutes / 10;
    return 0;
  }

  if (type === "bike") {
    if (Number.isFinite(miles) && miles > 0) return miles / 3;
    if (Number.isFinite(minutes) && minutes > 0) return minutes / 15;
    return 0;
  }

  if (type === "swim") {
    if (Number.isFinite(miles) && miles > 0) return miles * 4;
    if (Number.isFinite(minutes) && minutes > 0) return minutes / 12;
    return 0;
  }

  if (type === "workout") {
    let effortBonus = 1;
    if (feel === "easy") effortBonus = 1;
    else if (feel === "medium") effortBonus = 1.5;
    else if (feel === "hard") effortBonus = 2;

    if (Number.isFinite(minutes) && minutes > 0) {
      return (minutes / 20) * effortBonus;
    }
    return effortBonus;
  }

  // fallback
  if (Number.isFinite(miles) && miles > 0) return miles;
  if (Number.isFinite(minutes) && minutes > 0) return minutes / 10;
  return 0;
}

function getLevel(score, maxScore) {
  if (!score || score <= 0) return 0;
  if (!maxScore || maxScore <= 0) return 1;

  const ratio = score / maxScore;

  if (ratio <= 0.25) return 1;
  if (ratio <= 0.5) return 2;
  if (ratio <= 0.75) return 3;
  return 4;
}

export default function ActivityHeatmap({
  activities = [],
  weeksToShow = 53,
  showMonthLabels = true,
  title = "Activity Heatmap",
}) {
  const {
    weeks,
    monthLabels,
    totalActiveDays,
    maxScore,
  } = useMemo(() => {
    const totalsByDay = {};
    let earliestDate = null;

  for (const activity of activities) {
    const d = parseLocalYMD(activity?.date);
    if (!d || Number.isNaN(d.getTime())) continue;

    if (!earliestDate || d < earliestDate) {
      earliestDate = d;
    }

    const key = toYMD(d);
    const score = getActivityScore(activity);

    if (!score || score <= 0) continue;

    totalsByDay[key] = (totalsByDay[key] || 0) + score;
  }

    const today = startOfDay(new Date());
    const endDate = addDays(startOfWeekSunday(today), 6);

    let startDate;

    if (earliestDate) {
      startDate = startOfWeekSunday(earliestDate);
    } else {
      startDate = startOfWeekSunday(today);
    }

    const allDays = [];
    let cursor = new Date(startDate);

    while (cursor <= endDate) {
      const key = toYMD(cursor);

      allDays.push({
        date: new Date(cursor),
        key,
        score: totalsByDay[key] || 0,
      });

      cursor = addDays(cursor, 1);
    }

    const visibleMaxScore = Math.max(
      0,
      ...allDays.map((d) => d.score)
    );

    const weekColumns = [];
    for (let i = 0; i < allDays.length; i += 7) {
      weekColumns.push(allDays.slice(i, i + 7));
    }

    const labels = [];
    for (let i = 0; i < weekColumns.length; i++) {
      const week = weekColumns[i];
      const firstDay = week[0];
      if (!firstDay) continue;

      if (
        i === 0 ||
        !sameMonth(firstDay.date, weekColumns[i - 1]?.[0]?.date)
      ) {
        labels.push({
          index: i,
          text: firstDay.date.toLocaleString("en-US", { month: "short" }),
        });
      }
    }

    const activeDays = allDays.filter((d) => d.score > 0).length;

    return {
      weeks: weekColumns,
      monthLabels: labels,
      totalActiveDays: activeDays,
      maxScore: visibleMaxScore,
    };
  }, [activities, weeksToShow]);

  return (
    <div className="activity-heatmap-card">
      <div className="activity-heatmap-header">
        <h2 className="activity-heatmap-title">{title}</h2>
        <div className="activity-heatmap-sub">
          {totalActiveDays} active days logged
        </div>
      </div>

      <div className="activity-heatmap-shell">
        <div className="activity-heatmap-content">
          {showMonthLabels && (
            <div
              className="activity-heatmap-months"
              style={{ gridTemplateColumns: `repeat(${weeks.length}, 14px)` }}
            >
              {Array.from({ length: weeks.length }).map((_, i) => {
                const label = monthLabels.find((m) => m.index === i);
                return (
                  <div key={i} className="activity-heatmap-month-cell">
                    {label ? label.text : ""}
                  </div>
                );
              })}
            </div>
          )}

          <div className="activity-heatmap-main">
            <div className="activity-heatmap-days">
              <div></div>
              <div>Mon</div>
              <div></div>
              <div>Wed</div>
              <div></div>
              <div>Fri</div>
              <div></div>
            </div>

            <div
              className="activity-heatmap-grid"
              style={{ gridTemplateColumns: `repeat(${weeks.length}, 14px)` }}
            >
              {weeks.map((week, weekIndex) => (
                <div key={weekIndex} className="activity-heatmap-week">
                  {Array.from({ length: 7 }).map((_, dayIndex) => {
                    const day = week[dayIndex];
                    if (!day) {
                      return (
                        <div
                          key={dayIndex}
                          className="activity-heatmap-cell activity-heatmap-cell-empty"
                        />
                      );
                    }

                    const level = getLevel(day.score, maxScore);

                    return (
                      <div
                        key={day.key}
                        className={`activity-heatmap-cell level-${level}`}
                        title={`${day.key} • score: ${day.score.toFixed(2)}`}
                        aria-label={`${day.key} score ${day.score.toFixed(2)}`}
                      />
                    );
                  })}
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="activity-heatmap-footer">
          <div className="activity-heatmap-note">
            Full training history
          </div>

          <div className="activity-heatmap-legend">
            <span>Less</span>
            <div className="activity-heatmap-cell level-0" />
            <div className="activity-heatmap-cell level-1" />
            <div className="activity-heatmap-cell level-2" />
            <div className="activity-heatmap-cell level-3" />
            <div className="activity-heatmap-cell level-4" />
            <span>More</span>
          </div>
        </div>
      </div>


    </div>
  );
}

