source:
import React, { useEffect, useState, useMemo, useRef } from "react";
import LargeHeatmap from "../components/LargeHeatmap";
import EasyJar from "../components/profile/EasyJar";
// import WeeklyMileage from "../components/profile/WeeklyMileage";
import ProfileTopSection from "../components/profile/ProfileTopSection";
import PRPanel from "../components/profile/PRPanel";
import MonthlySnapshot from "../components/profile/MonthlySnapshot";
import PastJarsModal from "../components/profile/PastJarsModal";
import EditProfileModal from "../components/profile/EditProfileModal";
import TAG_OPTIONS from "../utils/tags";

import {
  formatTime,
  formatDate,
  parseDateSafe,
  parseDurationMinutes,
  startOfWeekSunday,
  addDays,
  weeksBetween,
  formatWeekRange,
  formatHoursMinsFromMinutes,
  chunkArray,
  getEasyZone,
  daysAgo,
} from "../utils/profileHelpers";



function hashString(str) {
  // deterministic hash for colors/positions
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function mulberry32(seed) {
  // deterministic PRNG
  return function () {
    let t = (seed += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}



export default function Profile() {
  const [activities, setActivities] = useState([]);
  const [avatar, setAvatar] = useState(() => localStorage.getItem("profileAvatar") || "");
  const [tag, setTag] = useState(
    () => localStorage.getItem("profileTag") || "Built Different (Unfortunately)"
  );
  const [profileName, setProfileName] = useState(
    () => localStorage.getItem("profileName") || "Your Name"
  );
  const fileInputRef = useRef(null);
  const [showJarHistory, setShowJarHistory] = useState(false);
  const [selectedPR, setSelectedPR] = useState(null);
  const [showTrends, setShowTrends] = useState(true);
  const [selectedWeekIndex, setSelectedWeekIndex] = useState(null);
  const [showEditProfile, setShowEditProfile] = useState(false);
  const [weeklyScaleMode, setWeeklyScaleMode] = useState(
  () => localStorage.getItem("weeklyScaleMode") || "dynamic"
);


  useEffect(() => {
    localStorage.setItem("profileTag", tag);
  }, [tag]);

  useEffect(() => {
      localStorage.setItem("profileName", profileName);
  }, [profileName]);

  useEffect(() => {
    localStorage.setItem("weeklyScaleMode", weeklyScaleMode);
  }, [weeklyScaleMode]);

  const handleAvatarChange = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // optional: limit size so localStorage doesn’t explode
    if (file.size > 2 * 1024 * 1024) {
        alert("Please choose an image under 2MB.");
        return;
    }

    const reader = new FileReader();
    reader.onload = () => {
        const dataUrl = reader.result; // base64 string
        setAvatar(dataUrl);
        localStorage.setItem("profileAvatar", dataUrl);
    };
    reader.readAsDataURL(file);
};

const removeAvatar = () => {
  setAvatar("");
  localStorage.removeItem("profileAvatar");
};

  useEffect(() => {
    const saved = localStorage.getItem("activities");
    if (saved) setActivities(JSON.parse(saved));
  }, []);

  // -------------------------
  // TOTAL / MONTH / YEAR
  // -------------------------
  const stats = useMemo(() => {
    let totalMiles = 0;
    let thisMonthMiles = 0;
    let thisYearMiles = 0;

    const now = new Date();

    activities.forEach((a) => {

    if (a.type && a.type !== "run") return;
      const miles = parseFloat(a.miles) || 0;
      totalMiles += miles;

      if (a.date) {
        const d = new Date(a.date);

        if (d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear()) {
          thisMonthMiles += miles;
        }
        if (d.getFullYear() === now.getFullYear()) {
          thisYearMiles += miles;
        }
      }
    });

    return {
      totalMiles,
      thisMonthMiles,
      thisYearMiles,
    };
  }, [activities]);

  // -------------------------
  // PRs (min time at distance)
  // -------------------------
    const prs = useMemo(() => {
        let bestMile = { time: Infinity, date: null };
        let best5k = { time: Infinity, date: null };
        let best10k = { time: Infinity, date: null };

        activities.forEach((a) => {
            if (a.type && a.type !== "run") return;

            const miles = parseFloat(a.miles);
            const duration = parseFloat(a.duration);
            if (!miles || !duration) return;

            const date = a.date || null;

            if (miles >= 1 && duration < bestMile.time) {
            bestMile = { time: duration, date };
            }

            if (miles >= 3.1 && duration < best5k.time) {
            best5k = { time: duration, date };
            }

            if (miles >= 6.2 && duration < best10k.time) {
            best10k = { time: duration, date };
            }
        });

        // Find most recent PR date
        const dates = [bestMile.date, best5k.date, best10k.date]
            .filter(Boolean)
            .map((d) => new Date(d));

        const latestPRDate =
            dates.length > 0
            ? new Date(Math.max(...dates.map((d) => d.getTime())))
            : null;

        return {
            mile: bestMile,
            fiveK: best5k,
            tenK: best10k,
            latestPRDate,
        };
  }, [activities]);




  // -------------------------
  // “5K box” value (use PR 5k)
  // -------------------------
  const fiveKDisplay = prs.fiveK;

    // -------------------------
    // EASY RUN JAR (25 easy runs per jar)
    // -------------------------
    const easyRuns = useMemo(() => {
        return activities
            .filter((a) => !a.type || a.type === "run")
            .filter((a) => a.intensity === "easy")
            .filter((a) => parseFloat(a.miles) && parseFloat(a.duration))
            .map((a, idx) => {
            const dateStr = a.date || "";
            // stable key: date+miles+duration+idx (good enough for local demo)
            const key = `${dateStr}|${a.miles}|${a.duration}|${idx}`;
            return {
                key,
                date: dateStr,
                miles: parseFloat(a.miles),
                duration: parseFloat(a.duration), // minutes
                label: "Easy Run",
            };
            })
            .sort((x, y) => new Date(x.date || 0) - new Date(y.date || 0));
    }, [activities]);

    const jarGroups = useMemo(() => chunkArray(easyRuns, 25), [easyRuns]);

    const currentJarIndex = Math.max(0, jarGroups.length - 1);
    const currentJar = jarGroups[currentJarIndex] || [];
    const completedJars = jarGroups.length > 1 ? jarGroups.slice(0, -1) : [];
    const jarCount = completedJars.length;
  

    // -------------------------
    // Monthly snapshot:
    // mileage, avg easy, % easy, longest
    // -------------------------
    const monthlySnapshot = useMemo(() => {
      const map = new Map();

      activities.forEach((a) => {
        if (a.type && a.type !== "run") return;

        const d = parseDateSafe(a.date);
        if (!d) return;

        const key = `${d.getFullYear()}-${d.getMonth()}`;

        if (!map.has(key)) {
        map.set(key, {
            label:
            d.toLocaleString("en-US", { month: "short" }) +
            " " +
            d.getFullYear(),
            mileage: 0,
            longest: 0,
            easyMiles: 0,
            totalMiles: 0,
            easyPaceSum: 0,
            easyPaceCount: 0,
            sortKey: new Date(d.getFullYear(), d.getMonth(), 1).getTime(),
        });
        }

        const m = map.get(key);

        const miles = Number(a.miles) || 0;
        const duration = parseDurationMinutes(a.duration);

        m.mileage += miles;
        m.totalMiles += miles;

        if (miles > m.longest) m.longest = miles;

        if (a.intensity === "easy" && miles > 0 && duration > 0) {
        m.easyMiles += miles;
        m.easyPaceSum += duration / miles;
        m.easyPaceCount += 1;
      }
    });

    const arr = Array.from(map.values())
        .sort((a, b) => b.sortKey - a.sortKey)
        // .slice(0, 12);

    return arr.map((m, index) => {
        const avgEasy = m.easyPaceCount
        ? formatTime(m.easyPaceSum / m.easyPaceCount)
        : "-";

        const pctEasy = m.totalMiles
        ? Math.round((m.easyMiles / m.totalMiles) * 100)
        : 0;

        const prev = arr[index + 1];

        let mileageDelta = null;
        let easyDelta = null;

        if (prev) {
        mileageDelta = m.mileage - prev.mileage;

        const prevPct = prev.totalMiles
            ? Math.round((prev.easyMiles / prev.totalMiles) * 100)
            : 0;

        easyDelta = pctEasy - prevPct;
        }

        return {
        month: m.label,
        mileage: m.mileage.toFixed(1),
        avgEasy,
        pctEasy,
        longest: m.longest.toFixed(1),
        mileageDelta,
        easyDelta,
        };
    });
    }, [activities]);

    
    // -------------------------
    // Weekly snapshot (Mon -> Sun) INCLUDING 0-mile weeks
    // builds all weeks from first run -> current week
    // -------------------------
    const weeklySnapshot = useMemo(() => {
        // 1) aggregate only the weeks that actually have runs
        const map = new Map();
        let earliestDate = null;

        activities.forEach((a) => {
            if (a.type && a.type !== "run") return;

            const d = parseDateSafe(a.date);
            if (!d) return;

            if (!earliestDate || d < earliestDate) earliestDate = d;

            const weekStart = startOfWeekSunday(d);
            const key = weekStart.toISOString().slice(0, 10);

            if (!map.has(key)) {
            map.set(key, {
                weekStart,
                miles: 0,
                minutes: 0,
                elevationFt: 0,
            });
            }

            const w = map.get(key);
            const miles = Number(a.miles) || 0;
            const minutes = parseDurationMinutes(a.duration);
            const elevation =
            Number(a.elevationGainFt ?? a.elevation_ft ?? a.elevationFt ?? a.elevation_gain_ft) || 0;

            w.miles += miles;
            w.minutes += minutes;
            w.elevationFt += elevation;
    });

    

    // 2) determine range (first week -> current week)
    const now = new Date();
    const endWeek = startOfWeekSunday(now);

    // If no runs yet, still return a single current week with 0s
    const startWeek = earliestDate ? startOfWeekSunday(earliestDate) : endWeek;

    // 3) generate EVERY week in the range (including zeros)
    const totalWeeks = weeksBetween(startWeek, endWeek);

    const out = [];
    for (let i = 0; i <= totalWeeks; i++) {
        const ws = addDays(startWeek, i * 7);
        const key = ws.toISOString().slice(0, 10);

        const found = map.get(key);

        out.push({
        label: formatWeekRange(ws),
        weekStart: ws,
        miles: found ? Number(found.miles.toFixed(1)) : 0,
        minutes: found ? Math.round(found.minutes) : 0,
        elevationFt: found ? Math.round(found.elevationFt) : 0,
        });
    }

    return out; // ascending by time
    }, [activities]);



    const selectedWeek =
    selectedWeekIndex != null ? weeklySnapshot[selectedWeekIndex] : null;

    const isThisWeek = useMemo(() => {
        if (!selectedWeek?.weekStart) return false;

        const now = new Date();
        const thisWeekStart = startOfWeekSunday(now);

        return (
            selectedWeek.weekStart.toISOString().slice(0, 10) ===
            thisWeekStart.toISOString().slice(0, 10)
        );
    }, [selectedWeek]);

    useEffect(() => {
        if (!weeklySnapshot.length) {
            setSelectedWeekIndex(null);
            return;
        }

        setSelectedWeekIndex(weeklySnapshot.length - 1);
    }, [weeklySnapshot]);

    const displayName = profileName.trim() || "Your Name";




    return (
      <div className="profile-page">

        <ProfileTopSection
          avatar={avatar}
          fileInputRef={fileInputRef}
          handleAvatarChange={handleAvatarChange}
          jarCount={jarCount}
          setShowJarHistory={setShowJarHistory}
          displayName={displayName}
          setShowEditProfile={setShowEditProfile}
          stats={stats}
          tag={tag}
          setTag={setTag}
          TAG_OPTIONS={TAG_OPTIONS}
        />
        

        {/* MIDDLE AREA: graph left + PR panel right */}
        <div className="profile-mid">

            {/* EASY JAR */}
            <div className="profile-panel">
            <EasyJar
                title="Easy Run Jar"
                subtitle={`${currentJar.length}/25 balls`}
                runs={currentJar}
            />

            {currentJar.length === 25 && (
                <div className="jar-complete">
                Jar complete! You’re officially annoying (in a good way). 🏆
                </div>
            )}
            </div>

            <PRPanel
              prs={prs}
              selectedPR={selectedPR}
              setSelectedPR={setSelectedPR}
            />

        </div>

            <MonthlySnapshot
              monthlySnapshot={monthlySnapshot}
              showTrends={showTrends}
              setShowTrends={setShowTrends}
            />

            <br></br>


        {showJarHistory && (
          <PastJarsModal
            showJarHistory={showJarHistory}
            setShowJarHistory={setShowJarHistory}
            completedJars={completedJars}
          />
        )}
        
        
        {showEditProfile && (
          <EditProfileModal
              showEditProfile={showEditProfile}
              setShowEditProfile={setShowEditProfile}
              profileName={profileName}
              setProfileName={setProfileName}
              weeklyScaleMode={weeklyScaleMode}
              setWeeklyScaleMode={setWeeklyScaleMode}
            />
        )}

        <LargeHeatmap activities={activities}/>

        </div>
    );
}

// src/utils/coachAlert.js

/* Why is this in utils and not in compoennts?
 Because this is logic, not UI

 The coach alert system is:
 Pure training logic that analyzes data and returns a result.
 That makes it a utility function, not a component.

*/

function isValidDate(d) {
  return d instanceof Date && !isNaN(d);
}

function toDate(activity) {
  const d = new Date(activity.date);
  return isValidDate(d) ? d : null;
}

function startOfWeek(date) {
  const d = new Date(date);
  const day = d.getDay(); // 0..6 (Sun..Sat)
  d.setHours(0, 0, 0, 0);
  d.setDate(d.getDate() - day);
  return d;
}

function endOfWeek(date) {
  const s = startOfWeek(date);
  const e = new Date(s);
  e.setDate(e.getDate() + 7);
  return e;
}

function sumMiles(list) {
  return list.reduce((acc, a) => acc + (Number(a.miles) || 0), 0);
}

// So it only looks at runs
function runOnly(list) {
  return list.filter(a => (a.type || "").toLowerCase() === "run");
}

function avgMph(list) {
  const vals = list.map(a => Number(a.mph)).filter(v => isFinite(v) && v > 0);
  if (!vals.length) return null;
  return vals.reduce((a, b) => a + b, 0) / vals.length;
}

function median(nums) {
  const arr = nums.slice().sort((a,b) => a-b);
  const n = arr.length;
  if (!n) return null;
  const mid = Math.floor(n / 2);
  return n % 2 ? arr[mid] : (arr[mid-1] + arr[mid]) / 2;
}

function daysSince(dateA, dateB) {
  const ms = (dateB.getTime() - dateA.getTime());
  return Math.floor(ms / (1000 * 60 * 60 * 24));
}

function isHardIntensity(intensity) {
  const i = (intensity || "").toLowerCase();
  return i === "tempo" || i === "hard" || i === "interval" || i === "race";
}

function easyRuns(activities) {
  return activities
    .filter(a => (a.type || "").toLowerCase() === "run")
    .filter(a => (a.intensity || "").toLowerCase() === "easy")
    .filter(a => isFinite(Number(a.mph)) && Number(a.mph) > 0);
}

function easyBaselineMph(activities, count = 10) {
  const easy = easyRuns(activities).slice(0, count); // newest-first
  if (easy.length < 4) return null;
  return avgMph(easy);
}

function getWeekSlice(sorted, now) {
  const ws = startOfWeek(now);
  const we = endOfWeek(now);

  const thisWeek = sorted.filter(a => {
    const d = toDate(a);
    return d && d >= ws && d < we;
  });

  const lastWeekStart = new Date(ws);
  lastWeekStart.setDate(lastWeekStart.getDate() - 7);
  const lastWeekEnd = new Date(ws);

  const lastWeek = sorted.filter(a => {
    const d = toDate(a);
    return d && d >= lastWeekStart && d < lastWeekEnd;
  });

  return { thisWeek, lastWeek, ws };
}

function countRunDaysLastNDays(sorted, now, nDays = 6) {
  // counts unique calendar days with at least one run
  const seen = new Set();
  for (const a of runOnly(sorted)) {
    const d = toDate(a);
    if (!d) continue;
    const diff = daysSince(d, now);
    if (diff < 0) continue;
    if (diff <= nDays) {
      seen.add(d.toISOString().slice(0, 10));
    }
  }
  return seen.size;
}

function findLongestRunInDays(sorted, now, days = 14) {
  let best = null;
  for (const a of runOnly(sorted)) {
    const d = toDate(a);
    if (!d) continue;
    const diff = daysSince(d, now);
    if (diff < 0 || diff > days) continue;
    if (!best || (Number(a.miles) || 0) > (Number(best.miles) || 0)) best = a;
  }
  return best;
}

function detectWallPattern(sorted, now) {
  // If last 4 runs are all within ~0.6 miles of each other (and under 4 miles), you're “stuck”
  const last = runOnly(sorted).slice(0, 5).filter(a => isFinite(Number(a.miles)) && Number(a.miles) > 0);
  if (last.length < 4) return null;

  const miles = last.slice(0, 4).map(a => Number(a.miles));
  const med = median(miles);
  if (!med) return null;

  const within = miles.every(m => Math.abs(m - med) <= 0.6);
  if (within && med <= 4.0) {
    return { med, sample: miles };
  }
  return null;
}

function easyDriftWarning(sorted) {
  // Compare recent easy mph vs baseline easy mph
  const baseline = easyBaselineMph(sorted, 10);
  const recentEasy = easyRuns(sorted).slice(0, 5);
  if (!baseline || recentEasy.length < 4) return null;

  const recentAvg = avgMph(recentEasy);
  if (!recentAvg) return null;

  // drift threshold (mph) – tweak later
  const drift = recentAvg - baseline;

  // Feel trend: if any of the recent easy runs felt medium/hard, flag more strongly
  const tougherFeelCount = recentEasy.filter(a => {
    const f = (a.feel || "").toLowerCase();
    return f === "medium" || f === "hard";
  }).length;

  if (drift >= 0.35 && tougherFeelCount >= 2) {
    return { baseline, recentAvg, drift };
  }

  return null;
}

export function generateCoachAlerts(activities, maxAlerts = 1) {
  const clampN = Math.max(0, Math.min(Number(maxAlerts) ?? 1, 6));

  // Priority (bigger = more important)
  const PRIORITY = {
    red: 4,
    yellow: 3,
    green: 2,
    blue: 1,
  };

  const make = (color, title, detail, key) => ({
    key,
    toneClass: `easy-zone-${color}`,
    title,
    detail,
    priority: PRIORITY[color] || 1,
  });

  if (!activities || activities.length === 0) {
    return [
      make(
        "blue",
        "Log your first run 👟",
        "Add a few runs and I’ll start giving coach notes.",
        "empty-first-run"
      ),
    ];
  }

  const sorted = runOnly(activities)
    .sort((a, b) => new Date(b.date) - new Date(a.date));
  const latest = sorted[0];
  const now = toDate(latest) || new Date();

  const { thisWeek, lastWeek } = getWeekSlice(sorted, now);

  const thisWeekMiles = sumMiles(runOnly(thisWeek));
  const lastWeekMiles = sumMiles(runOnly(lastWeek));

  const intensity = (latest.intensity || "").toLowerCase();
  const feel = (latest.feel || "").toLowerCase();
  const latestMph = Number(latest.mph);

  const alerts = [];
  const pushUnique = (alert) => {
    if (!alert) return;
    if (alerts.some((a) => a.key === alert.key)) return;
    alerts.push(alert);
  };

  // -------------------------
  // 🔴 RED (highest priority)
  // -------------------------

  // R1: Easy but felt hard
  if (intensity === "easy" && feel === "hard") {
    pushUnique(
      make(
        "red",
        "Marked easy… but it felt hard 🟥",
        "That’s a classic fatigue signal. Slow down next easy run or take a reset day.",
        "r1-easy-felt-hard"
      )
    );
  }

  // R2: Back-to-back hard efforts
  if (sorted.length >= 2) {
    const a0 = sorted[0], a1 = sorted[1];
    if (isHardIntensity(a0.intensity) && isHardIntensity(a1.intensity)) {
      pushUnique(
        make(
          "red",
          "Back-to-back hard days 🚨",
          "Stacking intensity is how tempo creep turns into burnout. Next run: easy or rest.",
          "r2-b2b-hard"
        )
      );
    }
  }

  // R3: “This wasn’t easy” pace creep vs baseline + feel medium/hard
  const baseline = easyBaselineMph(sorted, 10);
  const tooFastForEasy =
    intensity === "easy" &&
    baseline !== null &&
    isFinite(latestMph) &&
    latestMph > baseline + 0.4 &&
    (feel === "medium" || feel === "hard");

  if (tooFastForEasy) {
    pushUnique(
      make(
        "red",
        "That wasn’t easy 😅",
        `Easy pace creep: baseline ~${baseline.toFixed(1)} mph. Keep easy truly easy.`,
        "r3-easy-pace-creep"
      )
    );
  }

  // -------------------------
  // 🟡 YELLOW (caution)
  // -------------------------

  // Y1: 3+ hard efforts in last 7 days
  const last7 = sorted.slice(0, 12);
  const hardCount7 = last7.filter((a) => {
    const d = toDate(a);
    if (!d) return false;
    return daysSince(d, now) <= 7 && isHardIntensity(a.intensity);
  }).length;

  if (hardCount7 >= 3) {
    pushUnique(
      make(
        "yellow",
        "A lot of intensity this week ⚠️",
        `You’ve hit ${hardCount7} hard efforts in the last 7 days. Consider an easy reset.`,
        "y1-too-much-intensity"
      )
    );
  }

  // Y2: Mileage spike vs last week
  if (lastWeekMiles >= 1 && thisWeekMiles >= 1) {
    const change = ((thisWeekMiles - lastWeekMiles) / lastWeekMiles) * 100;
    if (change >= 25) {
      pushUnique(
        make(
          "yellow",
          `Mileage jump: +${Math.round(change)}% ⚠️`,
          `This week: ${thisWeekMiles.toFixed(1)} mi • Last week: ${lastWeekMiles.toFixed(1)} mi.`,
          "y2-mileage-spike"
        )
      );
    }
  }

  // Y3: No-rest-days pattern (ran 5+ of last 6 days)
  const runDays6 = countRunDaysLastNDays(sorted, now, 6);
  if (runDays6 >= 5) {
    pushUnique(
      make(
        "yellow",
        "No-rest pattern ⚠️",
        `You ran ${runDays6} of the last 6 days. A rest day can make you faster.`,
        "y3-no-rest"
      )
    );
  }

  // Y4: Easy pace drift upward + feel getting tougher
  const drift = easyDriftWarning(sorted);
  if (drift) {
    pushUnique(
      make(
        "yellow",
        "Easy pace is drifting (fatigue?) ⚠️",
        `Recent easy avg ~${drift.recentAvg.toFixed(1)} mph vs baseline ~${drift.baseline.toFixed(1)} mph.`,
        "y4-easy-drift"
      )
    );
  }

  // Y5: Wall pattern (stuck at same distance)
  const wall = detectWallPattern(sorted, now);
  if (wall) {
    pushUnique(
      make(
        "yellow",
        "You keep hitting the same wall 🧱",
        `Last runs cluster around ~${wall.med.toFixed(1)} mi. Try adding +0.2 mi on your next easy run.`,
        "y5-wall"
      )
    );
  }

  // Y6: Too little easy (this week)
  const totalCount = runOnly(thisWeek).length;
  const easyCount = runOnly(thisWeek)
    .filter((a) => (a.intensity || "").toLowerCase() === "easy").length;
  if (totalCount >= 3) {
    const easyPct = Math.round((easyCount / totalCount) * 100);
    if (easyPct <= 45) {
      pushUnique(
        make(
          "yellow",
          "Intensity imbalance ⚠️",
          `${easyPct}% easy this week. Consider making the next run a true easy day.`,
          "y6-easy-too-low"
        )
      );
    }
  }

  // -------------------------
  // 🟢 GREEN (praise)
  // -------------------------

  if (totalCount >= 3) {
    const easyPct = Math.round((easyCount / totalCount) * 100);
    if (easyPct >= 75) {
      pushUnique(
        make(
          "green",
          `Discipline week ✅ ${easyPct}% easy`,
          "This is how base gets built. Keep stacking.",
          "g1-discipline"
        )
      );
    }
  }

  if (lastWeekMiles >= 3 && thisWeekMiles >= 3) {
    const changeAbs = Math.abs((thisWeekMiles - lastWeekMiles) / lastWeekMiles) * 100;
    if (changeAbs <= 15 && totalCount >= 3) {
      pushUnique(
        make(
          "green",
          "Steady week ✅",
          `Mileage stayed stable (${thisWeekMiles.toFixed(1)} mi). Consistency is the cheat code.`,
          "g2-steady-week"
        )
      );
    }
  }

  if (sorted.length >= 2) {
    const d0 = toDate(sorted[0]);
    const d1 = toDate(sorted[1]);
    if (d0 && d1) {
      const gap = daysSince(d1, d0);
      if (gap >= 7) {
        pushUnique(
          make(
            "green",
            "Welcome back ✅",
            `You returned after ${gap} days. Keep it easy for a few runs and rebuild.`,
            "g3-comeback"
          )
        );
      }
    }
  }

  // -------------------------
  // 🔵 BLUE (informative)
  // -------------------------

  const longRun = sorted.find((a) => (a.intensity || "").toLowerCase() === "long");
  if (longRun) {
    const d = toDate(longRun);
    if (d) {
      const ds = daysSince(d, now);
      if (ds >= 14) {
        pushUnique(
          make(
            "blue",
            "Long run is overdue 👻",
            `Last long run was ${ds} days ago. Even a chill long run counts.`,
            "b1-long-overdue"
          )
        );
      }
    }
  }

  if (isHardIntensity(intensity)) {
    pushUnique(
      make(
        "blue",
        "Next move: easy reset 🧊",
        "You went hard last time. Keep the next run easy to actually get fitter.",
        "b2-next-move"
      )
    );
  }

  // Always have at least one message
  if (alerts.length === 0) {
    pushUnique(
      make(
        "blue",
        "Coach note: keep stacking reps 🧱",
        "Consistency beats hero workouts.",
        "b-default"
      )
    );
  }

  // Sort by priority (RED first), then keep stable order otherwise
  alerts.sort((a, b) => b.priority - a.priority);

  return alerts.slice(0, clampN);
}

export function generateCoachAlert(activities) {
  return generateCoachAlerts(activities, 1)[0];
}
